solution.solution.cpp:
#include <functional>
#include <map>
#include <string>
#include <vector>

struct Command
{
    std::string name;
    std::string shortcut;
    std::function<bool()> enabled;
    std::function<void()> run;
};

class Commands
{
public:
    void add(Command c) { m_commands.push_back(std::move(c)); }

    std::vector<std::string> clashes() const
    {
        std::map<std::string, std::vector<std::string>> byShortcut;
        for (const Command& c : m_commands) if (!c.shortcut.empty()) byShortcut[c.shortcut].push_back(c.name);
        std::vector<std::string> out;
        for (const auto& [shortcut, names] : byShortcut)
        {
            if (names.size() < 2) continue;
            std::string line{ shortcut + ": " };
            for (std::size_t i{ 0 }; i < names.size(); ++i) line += (i ? ", " : "") + names[i];
            out.push_back(line);
        }
        return out;
    }

    bool press(const std::string& shortcut)
    {
        for (Command& c : m_commands)
        {
            if (c.shortcut != shortcut || shortcut.empty()) continue;
            if (c.enabled && !c.enabled()) continue;
            if (c.run) c.run();
            return true;
        }
        return false;
    }

    std::vector<std::string> menu(const std::string& top) const
    {
        const std::string prefix{ top + "/" };
        std::vector<std::string> out;
        for (const Command& c : m_commands)
        {
            if (c.name.rfind(prefix, 0) != 0) continue;
            std::string item{ c.name.substr(prefix.size()) };
            if (!c.shortcut.empty()) item += "  " + c.shortcut;
            if (c.enabled && !c.enabled()) item += " (disabled)";
            out.push_back(item);
        }
        return out;
    }

private:
    std::vector<Command> m_commands;
};

unitTests:
TEST("menu items") {
    bool dirty = false; Commands c;
    c.add({ "File/New", "Ctrl+N", nullptr, [] {} });
    c.add({ "File/Save", "Ctrl+S", [&] { return dirty; }, [] {} });
    c.add({ "Edit/Undo", "Ctrl+Z", nullptr, [] {} });
    c.add({ "File/Quit", "", nullptr, [] {} });
    CHECK_EQ(c.menu("File"), (std::vector<std::string>{ "New  Ctrl+N", "Save  Ctrl+S (disabled)", "Quit" }));
    dirty = true; CHECK_EQ(c.menu("File")[1], std::string("Save  Ctrl+S"));
}
TEST("press runs the first enabled") {
    int saved = 0, selected = 0; bool canSave = false; Commands c;
    c.add({ "File/Save", "Ctrl+S", [&] { return canSave; }, [&] { ++saved; } });
    c.add({ "Edit/Select", "Ctrl+S", nullptr, [&] { ++selected; } });
    CHECK(c.press("Ctrl+S")); CHECK_EQ(saved, 0); CHECK_EQ(selected, 1);
    canSave = true; CHECK(c.press("Ctrl+S")); CHECK_EQ(saved, 1);
    CHECK(!c.press("Ctrl+Q")); CHECK(!c.press(""));
}
TEST("clashes") {
    Commands c;
    c.add({ "File/Save", "Ctrl+S", nullptr, nullptr }); c.add({ "Edit/Select", "Ctrl+S", nullptr, nullptr });
    c.add({ "View/Grid", "Ctrl+G", nullptr, nullptr }); c.add({ "Edit/Group", "Ctrl+G", nullptr, nullptr }); c.add({ "Edit/Undo", "Ctrl+Z", nullptr, nullptr });
    c.add({ "A", "", nullptr, nullptr }); c.add({ "B", "", nullptr, nullptr });
    CHECK_EQ(c.clashes(), (std::vector<std::string>{ "Ctrl+G: View/Grid, Edit/Group", "Ctrl+S: File/Save, Edit/Select" }));
}

